modele.css:
.card{font-family:-apple-system,Helvetica,Arial,sans-serif;font-size:18px;line-height:1.5;color:#1a1a1a;background:#fff;text-align:left;max-width:680px;margin:0 auto;padding:12px}
.q{font-size:20px;font-weight:600}
.part{font-size:12px;color:#888;letter-spacing:.04em;margin-bottom:8px}
hr#answer{border:none;border-top:1px solid #ddd;margin:16px 0}
.a{font-weight:bold;color:#ec5c07}
.o{font-style:italic;color:#ec5c07}
.d{font-weight:bold;color:#2d6517}
.c{font-weight:bold;color:#3c78d8}
.nightMode .card,.night_mode .card{background:#1e1e1e;color:#eee}
.nightMode .d,.night_mode .d{color:#7cc35f}
.nightMode .c,.night_mode .c{color:#79a6f0}
.exv{margin-top:12px;font-size:16px;font-style:italic;color:#555}
.nightMode .exv,.night_mode .exv{color:#bbb}
ol,ul{margin:6px 0;padding-left:24px}
li{margin:3px 0}
.titre{font-weight:700}
.bloc{background:#fff0f8;border-left:4px solid #dd88bb;border-radius:8px;padding:12px 15px;margin:10px 0}
.exemple{background:#edf7f0;border-left:4px solid #3aaa6a;border-radius:8px;padding:11px 15px;margin:10px 0;color:#000}
.rose{background:#fff1f5;border-left:4px solid #e05580;border-radius:8px;padding:11px 15px;margin:10px 0}
.orange{background:#fff8f0;border-left:4px solid #e08030;border-radius:8px;padding:11px 15px;margin:10px 0;color:#000}
.bleu{background:#eef7ff;border-left:4px solid #6aaaee;border-radius:8px;padding:11px 15px;margin:10px 0}
.dissert{background:#eeeaff;border-left:4px solid #5544cc;border-radius:8px;padding:11px 15px;margin:10px 0;font-style:italic;color:#1a0066}
.citation{background:#e3f0ff;border-left:4px solid #6aaaee;border-radius:8px;padding:11px 15px;margin:10px 0;font-style:italic;color:#1a1a1a}
.auteur{color:#ec5c07;font-weight:bold}
.oeuvre{color:#ec5c07;font-style:italic}
.date{color:#2d6517;font-weight:bold}
.nightMode .exemple,.nightMode .orange,.nightMode .rose,.nightMode .bloc,.nightMode .bleu,.nightMode .citation,.nightMode .dissert,.night_mode .exemple,.night_mode .orange,.night_mode .rose,.night_mode .bloc,.night_mode .bleu,.night_mode .citation,.night_mode .dissert{color:#111}
.nightMode div[style*="c5e6bd"],.night_mode div[style*="c5e6bd"]{color:#222}

img{max-width:100%;height:auto}
